<script setup lang="ts">import { MasonryRoot,MasonryVirtualViewport } from '@fex-design/vue/primitive/masonry';import Button from '@fex-design/vue/ui/button';import { nextTick,onMounted,ref } from 'vue';import { virtualMasonryItems } from './data';const host=ref<HTMLElement>(),expanded=ref<string[]>([]),mounted=ref(0),offset=ref(0);const update=(element:HTMLElement)=>{offset.value=element.scrollTop;mounted.value=element.querySelectorAll('[data-index]').length};const scrollTo=(index:number)=>{const viewport=host.value?.querySelector<HTMLElement>('[data-slot="masonry-virtual-viewport"]');if(viewport)viewport.scrollTo({top:index/virtualMasonryItems.length*(viewport.scrollHeight-viewport.clientHeight),behavior:'smooth'})};onMounted(()=>nextTick(()=>{const viewport=host.value?.querySelector<HTMLElement>('[data-slot="masonry-virtual-viewport"]');if(viewport)update(viewport)}))</script>
<template><div ref="host" class="grid gap-space-md"><div class="flex flex-wrap items-center gap-space-sm"><span class="text-sm">总数 5,000 · 当前挂载 {{mounted||'…'}} · scrollTop {{Math.round(offset)}}</span><Button size="sm" variant="outline" @click="scrollTo(0)">首项</Button><Button size="sm" variant="outline" @click="scrollTo(499)">第 500 项</Button><Button size="sm" variant="outline" @click="scrollTo(4999)">末项</Button></div><MasonryRoot :columns="{minColumnWidth:180,max:4}" :gap="12"><MasonryVirtualViewport :items="virtualMasonryItems" :get-item-key="item=>item.id" :estimate-size="item=>item.height" :height="420" class="rounded-md border border-border" @scroll="event=>update(event.currentTarget as HTMLElement)"><template #default="{item,index}"><article class="rounded-md border border-border bg-background p-space-md" :style="{minHeight:`${expanded.includes(item.id)?item.height+100:item.height}px`}"><strong>{{item.title}}</strong><p class="mt-2 text-xs text-muted-foreground">索引 {{index}} · TanStack measured lane</p><Button class="mt-2" size="sm" variant="outline" @click="expanded=expanded.includes(item.id)?expanded.filter(id=>id!==item.id):[...expanded,item.id]">{{expanded.includes(item.id)?'收起动态内容':'展开动态内容'}}</Button></article></template></MasonryVirtualViewport></MasonryRoot></div></template>
